// IPMA areas that get "Agitação Marítima" (sea state) warnings: the coastal
// districts, the three Açores groups and Madeira's coasts + Porto Santo.
// Inland districts and MRM (Madeira's mountain zone) never do.
// The sea band drawn for them on /mapa is generated by
// scripts/build-sea-bands.mjs into public/data/sea-bands.geojson — change the
// width here and re-run the script.

export const SEA_BAND_KM = 20

export const SEA_AREAS = [
	'VCT', 'BRG', 'PTO', 'AVR', 'CBR', 'LRA', 'LSB', 'STB', 'BJA', 'FAR',
	'AOC', 'ACE', 'AOR',
	'MCN', 'MCS', 'MPS',
]

export const SEA_WARNING_TYPE = 'Agitação Marítima'
